              due_at=datetime(2026, 1, 1, tzinfo=timezone.utc)),
        _task(3, "Done task", status=TaskStatus.DONE, tags=[Tag("shopping")]),
        _task(4, "Read book", priority=TaskPriority.LOW),
        _task(5, "Buy milk", tags=[Tag("shopping"), Tag("urgent")],
              due_at=datetime(2025, 4, 1, tzinfo=timezone.utc)),  # overdue
    ]


class TestTaskQueryValidation:
    def test_invalid_sort_field(self):
