    return Task(id=id, title=title, created_at=datetime(2025, 1, 1, tzinfo=timezone.utc))


class TestInMemoryTaskRepository:
    def test_add_and_get(self, repo):
        task = _make_task()
        repo.add(task)
        assert repo.get(1) == task

    def test_get_nonexistent(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(_make_task())
        with pytest.raises(ValueError, match="already exists"):
            repo.add(_make_task())

    def test_list_empty(self, repo):
        assert list(repo.list()) == []

    def test_list_returns_all(self, repo):
        repo.add(_make_task(1))
        repo.add(_make_task(2, "Second"))
        assert len(list(repo.list())) == 2

    def test_update(self, repo):
        task = _make_task()
        repo.add(task)
        task.title = "Updated"
        repo.update(task)
        assert repo.get(1).title == "Updated"

    def test_update_nonexistent_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(_make_task(99))

    def test_delete_existing(self, repo):
        repo.add(_make_task())
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_nonexistent(self, repo):
        assert repo.delete(999) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_deduplicates(self):
        tags = normalize_tags([Tag("foo"), Tag("FOO"), Tag("bar")])
        assert [t.name for t in tags] == ["foo", "bar"]

    def test_accepts_strings(self):
        tags = normalize_tags(["Hello", "World"])
        assert [t.name for t in tags] == ["hello", "world"]

    def test_preserves_order(self):
        tags = normalize_tags(["c", "a", "b"])
        assert [t.name for t in tags] == ["c", "a", "b"]

    def test_empty(self):
        assert normalize_tags([]) == []

