        assert page.offset == 3
        assert page.has_more is False

    def test_offset_beyond(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2, offset=10), NOW)
        assert len(page.items) == 0
        assert page.has_more is False


class TestTaskPage:
    def test_has_more_false_when_at_end(self):
